## 2️⃣ Minimal, production‑ready rewrite of `app.js`

Below is a **drop‑in replacement** that addresses all of the above items while keeping the original functionality unchanged.

```js
// app.js
/* -------------------------------------------------------------
 *  Secure & robust Express server
 *  - Centralised error handling
 *  - Security headers (helmet)
 *  - CORS policy
 *  - Rate limiting
 *  - Input validation scaffold (express-validator)
 *  - Graceful shutdown
 * ------------------------------------------------------------- */

require('dotenv').config();        // Loads .env (PORT, NODE_ENV, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator'); // future use
const pino = require('pino');      // lightweight logger
const logger = pino({ level: process.env.NODE_ENV === 'production' ? 'info' : 'debug' });

const app = express();

/* ---------- BASIC MIDDLEWARE ---------- */
app.use(express.json());          // Parse JSON bodies
app.use(helmet());                // Security headers
app.use(cors({                     // Adjust origins for your clients
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
}));
app.disable('x-powered-by');      // Hide Express fingerprint

/* ---------- RATE LIMITING ---------- */
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15‑minute window
  max: 100,                 // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // apply only to routes that need protection

/* ---------- ROUTES ---------- */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    env: process.env.NODE_ENV || 'development',
  });
});

app.get(
  '/users',
  // Example of query‑param validation (even if none are used today)
  [
    // query('page').optional().isInt({ min: 1 }).toInt(),
    // query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  ],
  (req, res, next) => {
    // If you ever add validation rules above, check them here:
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulated static data – replace with DB call in real app
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

/* ---------- 404 HANDLER ---------- */
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

/* ---------- GLOBAL ERROR HANDLER ---------- */
app.use((err, req, res, next) => {
  // Log the full stack trace for developers (only in dev)
  logger.error({ err, url: req.originalUrl, method: req.method }, err.message);

  // Do not leak internal details in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

/* ---------- SERVER STARTUP ---------- */
const PORT = normalizePort(process.env.PORT || '3000');
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

/* ---------- GRACEFUL SHUTDOWN ---------- */
function shutdown(signal) {
  logger.info(`Received ${signal}. Closing server…`);
  server.close(() => {
    logger.info('Server closed. Exiting process.');
    process.exit(0);
  });

  // Force exit after 10 seconds if still hanging
  setTimeout(() => {
    logger.warn('Force exiting after timeout.');
    process.exit(1);
  }, 10_000).unref();
}
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

/* ---------- HELPERS ---------- */
function normalizePort(val) {
  const port = parseInt(val, 10);
  if (Number.isNaN(port)) return val; // named pipe
  if (port >= 0) return port;        // valid port number
  return false;
}

module.exports = app;
```

### What changed?

| Change | Why it matters |
|--------|----------------|
| **`dotenv` + `process.env.PORT`** | Allows configuration via environment variables; avoids hard‑coded ports. |
| **`helmet`** | Sets a collection of HTTP headers that mitigate XSS, click‑jacking, MIME‑type sniffing, etc. |
| **`cors` with configurable origin** | Prevents browsers from making requests from unexpected origins. |
| **`disable('x-powered-by')`** | Hides the fact that the app runs on Express, reducing fingerprinting. |
| **`express-rate-limit`** | Throttles abusive IPs, limiting DoS vectors. |
| **`express.json()`** | Guarantees body parsing is present for any future POST/PUT routes. |
| **`express-validator` scaffold** | Shows how you would validate user input before using it. |
| **404 handler** | Guarantees every request receives a JSON response, not an HTML default page. |
| **Central error middleware** | Catches synchronous & asynchronous errors, logs them, and sends a generic error response in prod (no stack trace). |
| **Structured logging (`pino`)** | Gives you timestamps, log levels, and JSON output that plays nicely with log aggregators. |
| **Graceful shutdown** | Allows the process to finish in‑flight requests before exiting, important for container orchestration (K8s, Docker). |
| **`normalizePort` helper** | Mirrors the pattern used by the official Express generator, making the start‑up robust. |

