// app.js
// Revised – adds security, validation, and robust error handling

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');               // request logging
const { body, query, param, validationResult } = require('express-validator');
require('express-async-errors'); // patches express to forward async errors
const dotenv = require('dotenv');

dotenv.config(); // loads .env (optional)

const app = express();

// ---------- Security Middleware ----------
app.use(helmet()); // sets a sensible set of HTTP headers

// CORS – adjust the origin list as needed
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || false, // e.g., "https://example.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting – 100 requests / 15min per IP (tweak as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Body parsing & logging ----------
app.use(express.json({ limit: '10kb' })); // limit payload size
app.use(morgan('combined')); // structured request logs (replace with pino if you prefer)

// ---------- Helper to format validation errors ----------
const validate = (validations) => async (req, res, next) => {
  await Promise.all(validations.map((v) => v.run(req)));
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Respond with 400 Bad Request and a sanitized error payload
    return res.status(400).json({ errors: errors.array().map(e => e.msg) });
  }
  next();
};

