 * Example: /users?limit=10&page=2
 * We validate query params to prevent misuse.
 */
app.get(
  '/users',
  validate([
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
  ]),
  (req, res) => {
    // In a real app you’d fetch from DB and use limit/page safely.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// ---------- 404 Handler ----------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// ---------- Centralized Error Handler ----------
app.use((err, req, res, next) => {
  // Log the full error for internal visibility
  console.error(err); // replace with a proper logger in production

  // Do NOT expose stack traces or internal messages to callers
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/* Graceful shutdown */
const shutdown = () => {
  console.info('Shutting down server...');
  server.close(() => {
    console.info('Server closed.');
    process.exit(0);
  });
};
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

