/**
 * app.js – Refactored with security and error‑handling best practices
 * ---------------------------------------------------------------
 * Dependencies:
 *   npm i express helmet cors express-rate-limit morgan dotenv
 *   npm i express-validator   // optional, for request validation
 */

require('dotenv').config(); // loads .env, .env.test, etc.

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// -------------------------------------------------------------------
// 1️⃣ Global middleware – security, parsing, logging
// -------------------------------------------------------------------

// Helmet sets a sane set of HTTP security headers.
app.use(helmet());

// CORS – adjust the allowlist to your real front‑ends.
const allowedOrigins = process.env.CORS_ORIGINS
  ? process.env.CORS_ORIGINS.split(',') // e.g. "https://app.example.com,https://admin.example.com"
  : [];
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow REST clients (no origin) and whitelisted origins
      if (!origin || allowedOrigins.includes(origin)) {
        return callback(null, true);
      }
      return callback(new Error('Not allowed by CORS'));
    },
    credentials: true,
  })
);

// Rate limiting – 100 requests per 15 min per IP (tune to your traffic).
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true, // Return RateLimit-* headers
  legacyHeaders: false,
  message: {
    error: 'Too many requests, please try again later.',
  },
});
app.use(limiter);

// Body parser with size limit (avoid memory‑exhaustion attacks)
app.use(express.json({ limit: '100kb' })); // adjust as needed

// HTTP request logging – useful for audits & debugging.
// In production you may want to pipe to a file or external logger.
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// -------------------------------------------------------------------
// 2️⃣ Helper: async wrapper to forward errors to the error‑handler
// -------------------------------------------------------------------
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// -------------------------------------------------------------------
// 3️⃣ Routes
// -------------------------------------------------------------------

// Health‑check – never throws, minimal surface.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---- Example of a validated route ---------------------------------
/**
 * GET /users
 *   ?limit=10   – optional, integer 1‑100
 *   ?page=2     – optional, integer >=1
 *
 * Validation is done with express‑validator.  If validation fails,
 * the middleware returns a 400 response with a clear error payload.
 */
app.get(
  '/users',
  [
    // ---- Validation chain -------------------------------------------------
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be an integer >= 1'),
    // ---- Centralised validation result check ------------------------------
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        // Return first error (or you could return the whole array)
        return res.status(400).json({ error: errors.array()[0].msg });
      }
      next();
    },
  ],
  asyncHandler(async (req, res) => {
    // In a real app you would retrieve data from a DB using the validated params.
    // For now we just return static data (unchanged from the original file).
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  })
);

// -------------------------------------------------------------------
// 4️⃣ Centralised error handler
// -------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the error – in production you probably push to a log service.
  console.error(err); // Replace with a structured logger in real deployments.

  // Do not leak stack traces or internal messages in production.
  const status = err.status || 500;
  const response = {
    error:
      status === 500
        ? 'Internal server error'
        : err.message || 'Unexpected error',
  };

