// app.js – Secure, production‑ready starter
// ---------------------------------------------------------------
// 1️⃣ Imports & core middleware
// ---------------------------------------------------------------
const express = require('express');
const helmet = require('helmet');               // security headers
const cors = require('cors');                   // CORS handling
const rateLimit = require('express-rate-limit'); // basic DoS protection
const morgan = require('morgan');               // request logging
const { celebrate, Joi, errors, Segments } = require('celebrate'); // validation
const createError = require('http-errors');     // consistent error objects

const app = express();

// ---------------------------------------------------------------
// 2️⃣ General middleware
// ---------------------------------------------------------------
app.use(helmet());                     // sets CSP, HSTS, Referrer‑Policy, etc.
app.disable('x-powered-by');           // hide Express banner

// CORS – tighten to your own origins in production
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || '*', // whitelist via env var
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    credentials: true,
  })
);

// Rate limiting – adjust limits to your traffic profile
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // max 100 requests per IP per window
  message: { error: 'Too many requests, try again later.' },
});
app.use('/users', apiLimiter); // apply to state‑changing or heavy routes

// Request logging (use `combined` in production, `dev` locally)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Body parser – needed for any POST/PUT endpoints you add later
app.use(express.json());

// ---------------------------------------------------------------
// 3️⃣ Routes
// ---------------------------------------------------------------

// Health‑check – never throws, minimal surface
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *   – In a real app this would hit a DB; for demo we return static data.
 *   – Example of input validation on an optional query param `limit`.
 */
app.get(
  '/users',
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
    }),
  }),
  (req, res, next) => {
    try {
      const limit = req.query.limit;
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        // In a real DB call you would slice or paginate here.
      ].slice(0, limit);
      res.json(users);
    } catch (err) {
      next(err); // forward to our central error handler
    }
  }
);

/**
 * Example placeholder for a POST endpoint that receives user input.
 * Shows how you would validate the body before any business logic runs.
 */
app.post(
  '/users',
  celebrate({
    [Segments.BODY]: Joi.object({
      name: Joi.string().trim().min(2).max 100).required(),
      email: Joi.string().email().required(),
    }),
  }),
  async (req, res, next) => {
    try {
      // TODO: Insert user into DB, hash passwords, etc.
      const { name, email } = req.body;
      const newUser = { id: Date.now(), name, email };
      res.status(201).json(newUser);
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------
// 4️⃣ Celebrate validation error formatter
// ---------------------------------------------------------------
app.use(errors()); // automatically sends 400 with details (can be customized)

// ---------------------------------------------------------------
// 5️⃣ Central error handling middleware
// ---------------------------------------------------------------
app.use((err, req, res, next) => {
  // Unwrap Celebrate validation errors:
  if (err.joi) {
    return res.status(400).json({ error: 'Invalid request data', details: err.joi.details });
  }

  // Convert anything else to an HTTP error (defaults to 500)
  const httpError = createError(err.status || 500, err.message);
  const response = {
    error: httpError.message,
  };

  // In non‑production expose stack for debugging only
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  // Log the error (could be replaced with winston, pino, logfire, etc.)
  console.error(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`, err);

  res.status(httpError.statusCode).json(response);
});

// ---------------------------------------------------------------
// 6️⃣ Server bootstrap (graceful shutdown)
// ---------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown on SIGTERM / SIGINT
function shutdown() {
  console.log('Received shutdown signal – closing HTTP server...');
  server.close(() => {
    console.log('HTTP server closed.');
    // Close DB connections, flush logs, etc. here
    process.exit(0);
  });

  // Force close after 10 s
  setTimeout(() => {
    console.error('Force‑exiting after timeout.');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

// Catch unhandled promise rejections & uncaught exceptions
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // optional: process.exit(1);
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // optional: process.exit(1);
});

module.exports = app;
```

