```js
// validators/userQuery.js
const Joi = require('joi');

const schema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
});

function validateUserQuery(req, res, next) {
  const { error, value } = schema.validate(req.query, { abortEarly: false });
  if (error) {
    // Turn Joi validation errors into a proper HTTP 400 response
    const err = new Error('Invalid query parameters');
    err.status = 400;
    err.details = error.details.map(d => d.message);
    return next(err);
  }
  // Replace the original query with the validated/sanitised copy
  req.query = value;
  next();
}

module.exports = validateUserQuery;
```

